solution.solution.cpp:
#include <set>
#include <string>
#include <vector>

std::string missingFunctions(const std::set<std::string>& exports, const std::vector<std::string>& wanted)
{
    std::string out;
    for (const std::string& name : wanted)
    {
        if (exports.count(name)) continue;
        out += out.empty() ? "missing: " : ", ";
        out += name;
    }
    return out;
}

unitTests:
TEST("the example") { CHECK_EQ(missingFunctions({ "stackHeight", "stackWeight" }, { "stackHeight", "layers", "Stackweight" }), std::string("missing: layers, Stackweight")); }
TEST("all present") { CHECK_EQ(missingFunctions({ "a", "b" }, { "b", "a" }), std::string("")); }
TEST("nothing wanted") { CHECK_EQ(missingFunctions({ "a" }, {}), std::string("")); }
TEST("one missing") { CHECK_EQ(missingFunctions({}, { "go" }), std::string("missing: go")); }

